const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

// Función para convertir tiempo en formato HH:mm a minutos
function timeToMinutes(timeString) {
  if (!timeString || timeString === '0:00:00') return 0;
  const parts = timeString.split(':');
  return parseInt(parts[0]) * 60 + parseInt(parts[1]);
}

// Función para convertir minutos a formato HH:mm
function minutesToTime(minutes) {
  if (minutes === 0) return '00:00';
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  return `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
}

// Función para determinar la bahía según el ID del calendario
function determinarBahiaPorCalendario(data) {
  // Primero intentar obtener desde el organizador del evento de Google Calendar
  if (data.organizer && data.organizer.email) {
    const email = data.organizer.email.toLowerCase();

    // IDs de calendarios para Corrientes (3 bahías - reemplazar con los IDs reales)
    if (email.includes('corrientes-bahia1') || email === 'calendario_corrientes_bahia1@gmail.com') {
      return 'Corrientes - Bahía 1';
    }
    if (email.includes('corrientes-bahia2') || email === 'calendario_corrientes_bahia2@gmail.com') {
      return 'Corrientes - Bahía 2';
    }
    if (email.includes('corrientes-bahia3') || email === 'calendario_corrientes_bahia3@gmail.com') {
      return 'Corrientes - Bahía 3';
    }

    // ID de calendario para Mercedes (1 sola bahía - reemplazar con el ID real)
    if (email.includes('mercedes') || email === 'calendario_mercedes@gmail.com') {
      return 'Mercedes - Bahía Única';
    }
  }

  // Si viene del loop context o del Excel
  try {
    const loopItem = $("Loop Over Items").item.json;
    if (loopItem.calendar_id || loopItem.calendarId) {
      const calendarId = (loopItem.calendar_id || loopItem.calendarId).toLowerCase();

      // Mapear IDs de calendarios a bahías (reemplazar con los IDs reales)
      const calendarioBahias = {
        'calendario_corrientes_bahia1@gmail.com': 'Corrientes - Bahía 1',
        'calendario_corrientes_bahia2@gmail.com': 'Corrientes - Bahía 2',
        'calendario_corrientes_bahia3@gmail.com': 'Corrientes - Bahía 3',
        'calendario_mercedes@gmail.com': 'Mercedes - Bahía Única'
      };

      if (calendarioBahias[calendarId]) {
        return calendarioBahias[calendarId];
      }
    }
  } catch (error) {
    // No se pudo obtener del loop context
  }

  return 'Bahía no identificada';
}

// Función para determinar el taller base (sin bahía específica)
function determinarTallerBase(row) {
  if (row.Taller) {
    return row.Taller;
  }
  return 'Taller no identificado';
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let row = item.json;

  // CASO 1: Si viene de Google Calendar (tiene estructura de evento)
  if (row.start || row.summary || row.organizer) {
    const bahiaCompleta = determinarBahiaPorCalendario(row);

    // Verificar si tiene dateTime (eventos con hora específica)
    if (row.start && row.start.dateTime && row.end && row.end.dateTime) {
      const dia = row.start.dateTime.split('T')[0];
      const inicio = row.start.dateTime.split('T')[1].substring(0, 5);
      const final = row.end.dateTime.split('T')[1].substring(0, 5);

      returnItems.push({
        json: {
          dia: dia,
          inicio: inicio, 
          final: final,
          tipo: 'evento_calendario',
          titulo: row.summary || 'Sin título',
          bahia_completa: bahiaCompleta,
          calendario_email: row.organizer?.email || 'No disponible',
          taller: bahiaCompleta.split(' - ')[0] || 'No identificado',
          numero_bahia: bahiaCompleta.split(' - ')[1] || 'No identificado'
        }
      });
    }
    // Verificar si tiene date (eventos de día completo)
    else if (row.start && row.start.date) {
      const dia = row.start.date;

      returnItems.push({
        json: {
          dia: dia,
          inicio: '00:00', 
          final: '23:59',
          tipo: 'evento_dia_completo',
          titulo: row.summary || 'Sin título',
          bahia_completa: bahiaCompleta,
          calendario_email: row.organizer?.email || 'No disponible',
          taller: bahiaCompleta.split(' - ')[0] || 'No identificado',
          numero_bahia: bahiaCompleta.split(' - ')[1] || 'No identificado'
        }
      });
    }
    continue;
  }

  // CASO 2: Si viene del Excel (configuración de agenda)
  // Solo procesar filas que tengan tipo "Agenda"
  if (!row.Tipo || row.Tipo !== 'Agenda') {
    continue;
  }

  // Extraer información básica del Excel
  const tallerBase = determinarTallerBase(row);
  const orden = row.Orden || 0;

  // Procesar horarios de apertura y cierre
  const apertura = row.Apertura || '8:15:00';
  const cierre = row.Cierre || '17:00:00';

  // Procesar tiempos de recepción, lavado y entrega
  const recepcion = parseInt(row.Recepcion) || 15;
  const lavado = parseInt(row.Lavado) || 45;
  const entrega = parseInt(row.Entrega) || 15;

  // Procesar almuerzo
  const almuerzo = parseInt(row.Almuerzo) || 0;
  const inicioAlmuerzo = row['Inicio Almuerzo'] || '0:00:00';
  const finAlmuerzo = row['Fin Almuerzo'] || '0:00:00';

  // Procesar desayuno
  const desayuno = parseInt(row.Desayuno) || 0;
  const inicioDesayuno = row['Inicio Desayuno'] || '0:00:00';
  const finDesayuno = row['Fin Desayuno'] || '0:00:00';

  // Crear objeto con la información procesada del Excel
  const eventoProcessado = {
    json: {
      // Información básica
      taller: tallerBase,
      orden: orden,
      tipo: 'configuracion_agenda',

      // IMPORTANTE: Este registro del Excel no especifica bahía individual
      // La bahía específica se determinará cuando se procesen los eventos del calendario
      bahia_completa: `${tallerBase} - Configuración base`,

      // Horarios principales
      apertura: apertura.substring(0, 5), // Convertir de HH:mm:ss a HH:mm
      cierre: cierre.substring(0, 5),

      // Tiempos de proceso (en minutos)
      tiempo_recepcion: recepcion,
      tiempo_lavado: lavado,
      tiempo_entrega: entrega,

      // Información de almuerzo
      tiene_almuerzo: almuerzo > 0,
      duracion_almuerzo: almuerzo,
      inicio_almuerzo: inicioAlmuerzo !== '0:00:00' ? inicioAlmuerzo.substring(0, 5) : null,
      fin_almuerzo: finAlmuerzo !== '0:00:00' ? finAlmuerzo.substring(0, 5) : null,

      // Información de desayuno
      tiene_desayuno: desayuno > 0,
      duracion_desayuno: desayuno,
      inicio_desayuno: inicioDesayuno !== '0:00:00' ? inicioDesayuno.substring(0, 5) : null,
      fin_desayuno: finDesayuno !== '0:00:00' ? finDesayuno.substring(0, 5) : null,

      // Calcular tiempo total disponible para trabajo
      tiempo_total_disponible: timeToMinutes(cierre) - timeToMinutes(apertura) - almuerzo - desayuno,
      tiempo_total_proceso: recepcion + lavado + entrega,

      // Metadatos
      fecha_procesado: new Date().toISOString(),
      fila_original: row,

      // Nota importante
      nota: 'Esta es configuración base del taller. La bahía específica se determina por el ID del calendario.'
    }
  };

  returnItems.push(eventoProcessado);
}

return returnItems;

const items = [];
const inputs = $input.all();
let turnosOcupados = [];

// Procesar inputs para obtener turnos ocupados
for (let i = 0; i < inputs.length; i++) {
  if (inputs[i].json) {
    turnosOcupados.push(inputs[i].json);
  }
}

// Obtener configuración del webhook
const webhookData = $('When Executed by Another Workflow').first().json;
const configuracion = webhookData.body || webhookData;
const diasAGenerar = configuracion.dias || 7;

function convertirAMinutos(hora) {
  const [horas, minutos] = hora.split(':').map(Number);
  return horas * 60 + minutos;
}

function convertirDesdeMinutos(minutosTotales) {
  const horas = Math.floor(minutosTotales / 60);
  const minutos = minutosTotales % 60;
  return `${horas.toString().padStart(2, '0')}:${minutos.toString().padStart(2, '0')}`;
}

function generarSlots(horaInicio, horaFin, duracionMinutos) {
  const slots = [];
  const inicio = convertirAMinutos(horaInicio);
  const fin = convertirAMinutos(horaFin);

  for (let minutos = inicio; minutos + duracionMinutos <= fin; minutos += duracionMinutos) {
    const slotInicio = convertirDesdeMinutos(minutos);
    const slotFin = convertirDesdeMinutos(minutos + duracionMinutos);

    slots.push({
      inicio: slotInicio,
      fin: slotFin
    });
  }

  return slots;
}

function hayConflictoConOcupados(horaInicio, horaFin, turnosOcupados) {
  const inicioSlot = convertirAMinutos(horaInicio);
  const finSlot = convertirAMinutos(horaFin);

  return turnosOcupados.some(turno => {
    const inicioOcupado = convertirAMinutos(turno.inicio);
    const finOcupado = convertirAMinutos(turno.final);
    // Verificar si hay solapamiento
    return (inicioSlot < finOcupado && finSlot > inicioOcupado);
  });
}

function esHorarioExcluido(horaInicio, horaFin) {
  const inicioMinutos = convertirAMinutos(horaInicio);
  const finMinutos = convertirAMinutos(horaFin);

  // Rangos excluidos en minutos
  const rangosExcluidos = [
    { inicio: convertirAMinutos("08:30"), fin: convertirAMinutos("10:00") },  // 8:30 - 10:00 AM
    { inicio: convertirAMinutos("10:30"), fin: convertirAMinutos("15:00") },  // 10:30 AM - 3:00 PM
    { inicio: convertirAMinutos("15:30"), fin: convertirAMinutos("16:00") },  // 3:30 - 4:00 PM
    { inicio: convertirAMinutos("16:00"), fin: convertirAMinutos("23:59") }   // 4:00 PM en adelante
  ];

  // Verificar si el slot se solapa con algún rango excluido
  return rangosExcluidos.some(rango => {
    return (inicioMinutos < rango.fin && finMinutos > rango.inicio);
  });
}

function generarFechasProximosDias(cantidadDias) {
  const fechas = [];
  const hoy = new Date();

  // Lista de feriados
  const feriados = [
    '2025-01-01', '2025-03-03', '2025-03-04', '2025-03-24', 
    '2025-04-18', '2025-04-02', '2025-05-01', '2025-05-25', 
    '2025-06-20', '2025-07-09', '2025-08-17', '2025-10-12', 
    '2025-11-24', '2025-12-08', '2025-12-25'
  ];

  let diasEncontrados = 0;
  let i = 1;

  // Empezar desde mañana y buscar días laborables
  while (diasEncontrados < cantidadDias) {
    const fecha = new Date(hoy);
    fecha.setDate(hoy.getDate() + i);

    const fechaFormateada = fecha.toISOString().split('T')[0];
    const dayOfWeek = fecha.getDay(); // 0=domingo, 1=lunes, ..., 6=sábado

    // Verificar si es día laborable (lunes a viernes) y no es feriado
    const esLaborable = dayOfWeek >= 1 && dayOfWeek <= 5;
    const noEsFeriado = !feriados.includes(fechaFormateada);

    if (esLaborable && noEsFeriado) {
      fechas.push(fechaFormateada);
      diasEncontrados++;
    }

    i++;
  }

  return fechas;
}

function calcularTurnosDisponibles(turnosOcupados, configuracion, cantidadDias) {
  const tiempo = configuracion.tiempo || 30; // duración por defecto 30 minutos

  // Extraer rangos horarios de forma dinámica
  const rangosHorarios = [];
  let index = 1;

  while (configuracion[`horarioInicio${index}`] && configuracion[`horarioFin${index}`]) {
    rangosHorarios.push({
      inicio: configuracion[`horarioInicio${index}`],
      fin: configuracion[`horarioFin${index}`]
    });
    index++;
  }

  // Si no se encontraron rangos, usar un rango predeterminado
  if (rangosHorarios.length === 0) {
    rangosHorarios.push({
      inicio: "08:00",
      fin: "18:00"
    });
  }

  // Generar fechas para los próximos días
  const fechasProximas = generarFechasProximosDias(cantidadDias);

  const turnosDisponibles = {};

  // Procesar cada día
  fechasProximas.forEach(dia => {
    turnosDisponibles[dia] = [];

    // Obtener turnos ocupados para este día específico
    const ocupadosDelDia = turnosOcupados.filter(turno => turno.dia === dia);

    // Procesar cada rango horario configurado
    rangosHorarios.forEach(rango => {
      // Generar todos los slots posibles en este rango
      const slotsEnRango = generarSlots(rango.inicio, rango.fin, tiempo);

      // Filtrar slots que NO están ocupados y NO están en horarios excluidos
      const slotsDisponibles = slotsEnRango.filter(slot => {
        const noEstaOcupado = !hayConflictoConOcupados(slot.inicio, slot.fin, ocupadosDelDia);
        const noEsHorarioExcluido = !esHorarioExcluido(slot.inicio, slot.fin);
        return noEstaOcupado && noEsHorarioExcluido;
      }).map(slot => ({
        dia: dia,
        inicio: slot.inicio,
        fin: slot.fin,
        fechaHora: `${dia} ${slot.inicio}-${slot.fin}`
      }));

      // Añadir slots disponibles al día
      turnosDisponibles[dia].push(...slotsDisponibles);
    });

    // Ordenar turnos por hora de inicio
    turnosDisponibles[dia].sort((a, b) => {
      const minutosA = convertirAMinutos(a.inicio);
      const minutosB = convertirAMinutos(b.inicio);
      return minutosA - minutosB;
    });
  });

  return turnosDisponibles;
}

// Calcular turnos disponibles
const resultado = calcularTurnosDisponibles(turnosOcupados, configuracion, diasAGenerar);

// Agregar estadísticas útiles
const estadisticas = {
  totalDias: Object.keys(resultado).length,
  totalTurnosDisponibles: Object.values(resultado).reduce((total, turnos) => total + turnos.length, 0),
  diasConTurnos: Object.entries(resultado).filter(([_, turnos]) => turnos.length > 0).length,
  turnosOcupadosRecibidos: turnosOcupados.length
};

items.push({
